<?php
$headlines = ['Pending' => 'Waiting for confirmation', 'Confirmed' => 'Your order is being prepared', 'Shipped' => 'Your order is on its way', 'Delivered' => 'Delivered. Enjoy your produce.', 'Cancelled' => 'This order was cancelled'];
$stageLabels = ['Pending' => 'Placed', 'Confirmed' => 'Confirmed', 'Shipped' => 'On the way', 'Delivered' => 'Delivered'];
$liveTracking = $is_owner && current_role() === 'Buyer';
?>
<div <?= $liveTracking ? 'data-order-tracking data-order-id="' . (int)$order['order_id'] . '"' : '' ?>>
<div class="page-heading"><div><span class="eyebrow">FROM FARM TO YOUR DOOR</span><h1>Order #<?= (int)$order['order_id'] ?></h1><p>Placed <?= e(date('d M Y · H:i', strtotime($order['order_date']))) ?> · <?= e($order['buyer_name']) ?></p></div><a class="btn btn-outline-success" href="<?= current_role() === 'Buyer' ? 'my_orders.php' : (current_role() === 'Farmer' ? 'farmer_orders.php' : 'admin_orders.php') ?>">← All orders</a></div>
<div class="tracking-banner"><div><span class="eyebrow">ORDER PROGRESS</span><h2 id="tracking-headline"><?= e($headlines[$order['status']]) ?></h2><p id="tracking-status"><?= e($order['status']) ?> · We'll keep your delivery updates here.</p></div><div class="eta-block"><small>EXPECTED DELIVERY</small><strong id="expected-delivery"><?= $order['estimated_delivery_date'] ? e(date('d M Y', strtotime($order['estimated_delivery_date']))) : 'Awaiting confirmation' ?></strong><small id="expected-window"><?= e($order['estimated_delivery_window'] ?? '') ?></small></div></div>
<div class="tracking-tools"><p id="tracking-updated">Checked at <?= e(date('H:i:s')) ?> · Updates every 30 seconds while this page is open.</p><?php if ($liveTracking): ?><button id="refresh-tracking" class="btn btn-outline-success" type="button">Refresh updates</button><?php else: ?><a href="order.php?id=<?= (int)$order['order_id'] ?>" class="btn btn-outline-success">Refresh updates</a><?php endif; ?></div>
<p id="tracking-notice" class="tracking-note" role="status" aria-live="polite">Delivery progress is updated by the farmer. Location is not tracked.</p>
<div class="tracking-grid"><div class="tracking-stack"><section class="card"><ol class="order-progress" aria-label="Delivery stages"><?php foreach ($stageLabels as $status => $label): $index = array_search($status, $statuses); ?><li data-step="<?= e($status) ?>" class="<?= $current_index !== false && $index < $current_index ? 'complete' : ($order['status'] === $status ? 'current' : '') ?>" <?= $order['status'] === $status ? 'aria-current="step"' : '' ?>><span class="step-dot"><?= $index + 1 ?></span><?= e($label) ?></li><?php endforeach; ?></ol><div class="card-body"><h2 class="section-title">Delivery updates</h2><ol class="timeline" id="timeline-events"><?php foreach ($events as $event): ?><li><strong><?= e($event['status']) ?></strong><p><?= e($event['note']) ?></p><time datetime="<?= e(date(DATE_ATOM, (int)$event['event_epoch'])) ?>"><?= e(date('d M Y · H:i', (int)$event['event_epoch'])) ?></time></li><?php endforeach; ?><?php if (!$events): ?><li><strong><?= e($order['status']) ?></strong><p>No earlier status updates were recorded.</p></li><?php endif; ?></ol></div></section>
<section class="card"><div class="card-header">Your items</div><div class="table-responsive"><table class="table tracking-table"><thead><tr><th>Produce</th><th>Quantity</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['product_name']) ?><small>From <?= e($item['farmer_name']) ?></small></td><td><?= (int)$item['quantity'] ?> <?= e($item['unit']) ?></td><td><?= format_money($item['quantity'] * $item['unit_price']) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><td colspan="2" class="fw-bold">Order total</td><td class="fw-bold"><?= format_money($order['total_amount']) ?></td></tr></tfoot></table></div></section></div>
<div class="tracking-stack"><section class="card"><div class="card-body"><h2 class="section-title">Delivery &amp; payment</h2><span class="info-label">Deliver to</span><div class="address-block"><?= nl2br(e($order['delivery_address'])) ?></div><span class="info-label">Payment details</span><div id="tracking-payments"><?php foreach ($txns as $transaction): ?><div class="payment-row"><span><?= e($transaction['payment_method']) ?><small class="d-block text-muted"><?= format_money($transaction['amount']) ?></small></span><span class="badge bg-<?= $transaction['payment_status'] === 'Completed' ? 'success' : ($transaction['payment_status'] === 'Failed' ? 'danger' : 'warning') ?>"><?= e($transaction['payment_status']) ?></span></div><?php endforeach; ?></div></div></section>
<section class="card"><div class="card-body"><h2 class="section-title">Need an update?</h2><p class="small text-muted">Contact your farmer for delivery arrangements or questions about your produce.</p><?php $contacted = []; foreach ($items as $item): if (isset($contacted[$item['farmer_id']])) continue; $contacted[$item['farmer_id']] = true; ?><div class="contact-farmer"><span><?= e($item['farmer_name']) ?></span><a href="messages.php?to=<?= (int)$item['farmer_id'] ?>">Message →</a></div><?php endforeach; ?></div></section>
<?php if ($liveTracking && $order['status'] === 'Pending'): ?><section class="card" id="cancel-order-section"><div class="card-body"><h2 class="section-title">Changed your plans?</h2><p class="small text-muted">You can cancel while this order is waiting for confirmation.</p><form method="post" onsubmit="return confirm('Cancel this order?');"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><button class="btn btn-outline-danger w-100">Cancel order</button></form></div></section><?php endif; ?>
</div></div></div>
